"""Keep existing signed sessions valid while rejecting forged or expired JWTs."""
import unittest
from datetime import timedelta
from unittest.mock import patch

import jwt
from fastapi import HTTPException
from app import auth

KEY = 'compatibility-test-key-0123456789-ABCDEFGHIJKLMNOPQRSTUVWXYZ'
# Generated by python-jose 3.5.0 with the test key above, not a production token.
LEGACY_TOKEN = ('eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.'
                'eyJzdWIiOiJsZWdhY3ktdXNlciIsInNpZCI6ImV4aXN0aW5nLXNlc3Npb24iLCJkaWQiOiJleGlzdGluZy1kZXZpY2UiLCJpYXQiOjE3MDAwMDAwMDAsImV4cCI6NDEwMjQ0NDgwMH0.'
                'R8s8rtCVfC6tNwfHtempTwE1Rt1FpKKHv7zhHC3u1cA')


class JwtCompatibilityTests(unittest.TestCase):
    def test_existing_session_token_stays_valid(self):
        with patch.object(auth, 'SECRET_KEY', KEY):
            payload = auth.decode_token(LEGACY_TOKEN)
        self.assertEqual(payload['sub'], 'legacy-user')
        self.assertEqual(payload['sid'], 'existing-session')
        self.assertEqual(payload['did'], 'existing-device')

    def test_new_token_roundtrip_does_not_change_session_claims(self):
        data = dict(sub='user', sid='session', did='device')
        with patch.object(auth, 'SECRET_KEY', KEY):
            token = auth.create_access_token(data, timedelta(minutes=5))
            decoded = auth.decode_token(token)
        self.assertEqual({key: decoded[key] for key in data}, data)
        self.assertEqual(decoded['exp'] - decoded['iat'], 300)
        self.assertEqual(data, dict(sub='user', sid='session', did='device'))

    def test_invalid_expired_or_wrong_algorithm_tokens_are_rejected(self):
        bad = [
            jwt.encode(dict(sub='user', exp=1), KEY, algorithm='HS256'),
            jwt.encode(dict(sub='user'), 'wrong-key-0123456789-ABCDEFGHIJKLMNOPQRSTUVWXYZ', algorithm='HS256'),
            jwt.encode(dict(sub='user'), KEY, algorithm='HS512'),
            jwt.encode(dict(sub='user'), key='', algorithm='none'),
            'not-a-token',
        ]
        with patch.object(auth, 'SECRET_KEY', KEY):
            for token in bad:
                with self.subTest(token=token), self.assertRaises(HTTPException) as error:
                    auth.decode_token(token)
                self.assertEqual(error.exception.status_code, 401)
